// Package locales embeds the ICU MessageFormat catalogs shared by the server and the clients
// (ADR-0009). Each file is locales/<BCP47>/<namespace>.json in the FormatJS JSON shape;
// en is the source locale, en-XA and ar-XB are pseudo-locales generated by tools/i18n.
// Only internal/i18n reads this package.
package locales

import "embed"

// FS holds the <locale>/<namespace>.json catalog files of the namespaces Go formats: every namespace
// but client*, which only the TypeScript clients read and whose pseudo-locales are not committed
// (ADR-0081). A new namespace Go formats needs its pattern here; TestFS fails until it has one.
//
//go:embed */server.json
var FS embed.FS
